/**
 * Bundled model catalog (generated by `scripts/build-catalog.mjs`) plus helpers
 * used by the model picker and the reasoning selector.
 */
import catalogJson from '@data/catalog.json';
import { t } from './i18n';
import { compareText } from './i18n/format';
import type {
  CatalogFile,
  ModelInfo,
  ModelSelection,
  ProviderAuth,
  ProviderInfo,
  ReasoningOption,
  ReasoningSelection,
  RequestProfile,
  Settings,
} from './types';

export const catalog = catalogJson as unknown as CatalogFile;

export function providers(): ProviderInfo[] {
  return catalog.providers;
}

/**
 * Providers curated as "Popular providers" in Settings. They are always offered
 * by the model selector (even before a credential exists, so the missing-key
 * call to action stays reachable); every other provider appears there only once
 * it has a stored credential or a connected account.
 */
export const CURATED_PROVIDER_IDS: readonly string[] = [
  'opencode-go',
  'opencode-zen',
  'openai',
  'anthropic',
  'gemini',
];

/** True when the provider belongs to the curated "popular" set. */
export function isCuratedProvider(providerId: string): boolean {
  return CURATED_PROVIDER_IDS.includes(providerId);
}

export function getProvider(providerId: string): ProviderInfo | undefined {
  return findProviderIn(catalog.providers, providerId);
}

export function findProviderIn(
  list: readonly ProviderInfo[],
  providerId: string,
): ProviderInfo | undefined {
  return list.find((p) => p.id === providerId);
}

export function getModel(providerId: string, modelId: string): ModelInfo | undefined {
  return findModelIn(catalog.providers, providerId, modelId);
}

export function findModelIn(
  list: readonly ProviderInfo[],
  providerId: string,
  modelId: string,
): ModelInfo | undefined {
  return findProviderIn(list, providerId)?.models.find((m) => m.id === modelId);
}

/** Authentication mode, defaulting to API key for older catalogs. */
export function providerAuth(provider: ProviderInfo | undefined): ProviderAuth {
  return provider?.auth ?? 'api-key';
}

/** Request profile for a provider + credential kind. */
export function requestProfileFor(
  provider: ProviderInfo | undefined,
  credential: ProviderAuth,
): RequestProfile {
  if (!provider) return 'standard';
  return (credential === 'oauth' ? provider.requestProfiles?.oauth : provider.requestProfiles?.apiKey) ?? 'standard';
}

/** True when the provider can use the user's ChatGPT plan (OAuth flow). */
export function providerSupportsPlan(provider: ProviderInfo | undefined): boolean {
  return provider?.auth === 'oauth' && Boolean(provider.oauth);
}

export function findModel(modelId: string): { provider: ProviderInfo; model: ModelInfo } | null {
  for (const provider of catalog.providers) {
    const model = provider.models.find((m) => m.id === modelId);
    if (model) return { provider, model };
  }
  return null;
}

export function providerLabel(providerId: string): string {
  return getProvider(providerId)?.shortName ?? providerId;
}

export function defaultSelection(settings?: Settings | null): ModelSelection {
  return defaultSelectionFrom(settings, catalog.providers);
}

/**
 * Same selection policy as {@link defaultSelection}, but against a caller
 * supplied provider list (the renderer uses the merged `CatalogView` list so
 * account-only models survive a restart).
 */
export function defaultSelectionFrom(
  settings: Settings | null | undefined,
  list: readonly ProviderInfo[],
): ModelSelection {
  const providerId = settings?.defaultProvider ?? 'opencode-go';
  const provider = findProviderIn(list, providerId) ?? list[0];
  const configured = settings?.defaultModel;
  const modelId =
    configured && provider?.models.some((m) => m.id === configured)
      ? configured
      : (provider?.defaultModelId ?? provider?.models[0]?.id ?? '');
  const model = provider?.models.find((m) => m.id === modelId);
  return {
    providerId: provider?.id ?? providerId,
    modelId,
    reasoning: resolveReasoningDefault(settings?.reasoningDefault, model),
  };
}

/**
 * Applies the persisted preference against the model's own reasoning options.
 * Unknown, disabled or out-of-range values fall back to the model default; no
 * value is ever invented or sent to a provider that did not declare it.
 */
export function resolveReasoningDefault(
  preferred: string | null | undefined,
  model?: ModelInfo | null,
): ReasoningSelection | null {
  const fallback = defaultReasoningFor(model);
  if (!preferred || preferred === 'auto') return fallback;
  const ui = reasoningUi(model);
  if (!ui.supported) return null;
  if (preferred === 'off') return ui.canDisable ? { mode: 'off' } : fallback;

  const budget = preferred.match(/^budget:(\d{1,7})$/);
  if (budget) {
    if (!ui.budget) return fallback;
    const value = Number(budget[1]);
    const clamped = Math.min(ui.budget.max ?? 65_536, Math.max(ui.budget.min ?? 1_024, value));
    return { mode: 'budget', budget: clamped };
  }

  const effort = preferred.startsWith('effort:') ? preferred.slice(7) : preferred;
  if (!effort || !ui.efforts.includes(effort)) return fallback;
  return { mode: 'effort', effort };
}

/** Picks the first available reasoning option as the default. */
export function defaultReasoningFor(model?: ModelInfo | null): ReasoningSelection | null {
  if (!model) return null;
  const hasToggle = model.reasoningOptions.some((o) => o.type === 'toggle');
  const effort = model.reasoningOptions.find((o) => o.type === 'effort') as
    | { type: 'effort'; values: string[] }
    | undefined;
  if (effort) {
    // Default to a balanced effort when the model exposes one.
    const preferred = ['medium', 'high', 'low', 'max', 'xhigh', 'minimal'].find((v) =>
      effort.values.includes(v),
    );
    return { mode: 'effort', effort: preferred ?? effort.values[0] ?? null };
  }
  if (hasToggle) return { mode: 'off' };
  const budget = model.reasoningOptions.find((o) => o.type === 'budget_tokens') as
    | { type: 'budget_tokens'; min?: number; max?: number }
    | undefined;
  if (budget) {
    // Budget-only models have no on/off switch: always send a concrete budget so
    // the slider value shown in the UI matches what is committed.
    const min = budget.min ?? 1_024;
    const max = budget.max ?? 65_536;
    return { mode: 'budget', budget: Math.min(max, Math.max(min, 8_192)) };
  }
  return null;
}

export interface ReasoningUi {
  /** false when the model has no reasoning control at all */
  supported: boolean;
  canDisable: boolean;
  efforts: string[];
  budget: { min: number | null; max: number | null } | null;
  /** the reasoning options that are meaningful for this model */
  options: ReasoningOption[];
}

export function reasoningUi(model?: ModelInfo | null): ReasoningUi {
  if (!model) {
    return { supported: false, canDisable: false, efforts: [], budget: null, options: [] };
  }
  const options = model.reasoningOptions ?? [];
  const toggle = options.find((o) => o.type === 'toggle');
  const effort = options.find((o) => o.type === 'effort') as
    | { type: 'effort'; values: string[] }
    | undefined;
  const budget = options.find((o) => o.type === 'budget_tokens') as
    | { type: 'budget_tokens'; min?: number; max?: number }
    | undefined;
  return {
    supported: Boolean(toggle || effort || budget),
    canDisable: Boolean(toggle) || Boolean(effort?.values.includes('none')),
    efforts: effort?.values ?? [],
    budget: budget ? { min: budget.min ?? 1024, max: budget.max ?? 65536 } : null,
    options,
  };
}

/** Human label for an effort value. */
export function effortLabel(effort: string): string {
  switch (effort) {
    case 'none':
      return t('models:effort.none');
    case 'minimal':
      return t('models:effort.minimal');
    case 'low':
      return t('models:effort.low');
    case 'medium':
      return t('models:effort.medium');
    case 'high':
      return t('models:effort.high');
    case 'xhigh':
      return t('models:effort.xhigh');
    case 'max':
      return t('models:effort.max');
    default:
      return effort;
  }
}

/** Compact reasoning label used inside pills (e.g. "Máx."). */
export function reasoningShortLabel(
  model: ModelInfo | undefined,
  selection: ReasoningSelection | null | undefined,
): string {
  if (!model || !reasoningUi(model).supported) return '';
  if (!selection || selection.mode === 'off') {
    return reasoningUi(model).canDisable ? t('models:reasoning.shortOff') : '';
  }
  if (selection.mode === 'effort') {
    return selection.effort ? effortLabel(selection.effort) : t('models:reasoning.shortOn');
  }
  if (selection.mode === 'budget') return String(selection.budget ?? 0);
  return '';
}

export function reasoningLabel(
  model: ModelInfo | undefined,
  selection: ReasoningSelection | null | undefined,
): string {
  if (!model || !reasoningUi(model).supported) return t('models:reasoning.noControl');
  if (!selection || selection.mode === 'off') {
    return reasoningUi(model).canDisable
      ? t('models:reasoning.thinkingOff')
      : t('models:reasoning.default');
  }
  if (selection.mode === 'effort') {
    if (!selection.effort) return t('models:reasoning.thinkingOn');
    return t('models:reasoning.effortLabel', { effort: effortLabel(selection.effort) });
  }
  if (selection.mode === 'budget') {
    return t('models:reasoning.budget', { value: selection.budget ?? 0 });
  }
  return t('models:reasoning.default');
}

export function formatContextWindow(tokens: number): string {
  if (!tokens) return '—';
  if (tokens >= 1_000_000) {
    // 1_048_576 is "1M", not "1.0M": round to one decimal and drop the ".0".
    const rounded = Math.round((tokens / 1_000_000) * 10) / 10;
    return Number.isInteger(rounded) ? `${rounded.toFixed(0)}M` : `${rounded.toFixed(1)}M`;
  }
  if (tokens >= 1000) return `${Math.round(tokens / 1000)}K`;
  return String(tokens);
}

export function formatPrice(cost?: ModelInfo['cost']): string {
  if (!cost || cost.input == null || cost.output == null) return '—';
  if (cost.input === 0 && cost.output === 0) return t('models:price.free');
  const fmt = (v: number) => (v === 0 ? t('models:price.freeShort') : `$${v.toFixed(2)}`);
  return t('models:price.pair', { input: fmt(cost.input), output: fmt(cost.output) });
}

export function modelBadges(model: ModelInfo): string[] {
  const badges: string[] = [];
  if (model.status === 'free') badges.push(t('models:badges.free'));
  if (model.tags.includes('vision') || model.attachment) badges.push(t('models:badges.vision'));
  if (model.reasoningOptions.length) badges.push(t('models:badges.reasoning'));
  if (model.openWeights) badges.push(t('models:badges.open'));
  if (model.status === 'beta') badges.push(t('models:badges.preview'));
  if (model.status === 'unavailable') badges.push(t('models:badges.unavailable'));
  return badges;
}

export function supportsAttachments(model?: ModelInfo | null): boolean {
  if (!model) return false;
  return model.attachment || model.modalities.input.includes('image');
}

/** Group models by family for the picker list. */
export function groupByFamily(models: ModelInfo[]): { family: string; models: ModelInfo[] }[] {
  const map = new Map<string, ModelInfo[]>();
  for (const model of models) {
    const family = model.family || 'outros';
    const list = map.get(family) ?? [];
    list.push(model);
    map.set(family, list);
  }
  return [...map.entries()]
    .map(([family, list]) => ({
      family,
      models: list.sort((a, b) => compareText(a.name, b.name)),
    }))
    .sort((a, b) => compareText(a.family, b.family));
}

export const CATALOG_GENERATED_AT = catalog.generatedAt;
